        if (!$coupon) {
            return ['valid' => false, 'message' => 'Cupom não encontrado.'];
        }

        // Verifica se o cupom já foi usado (para cupons de uso único)
        if ($id && $coupon->for_new_users === 1) {
            $already_used = $this->coupons_model->check_coupon_used($code);
            if ($already_used) {
                return ['valid' => false, 'message' => 'Este cupom já foi utilizado.'];
            }
        }

        // Verifica se o cupom está ativo
        if ($coupon->status !== 'active') {
            return ['valid' => false, 'message' => 'Este cupom não está ativo.'];
        }

        // Verifica se a data atual está dentro do período de validade
        $now = date('Y-m-d H:i:s');

        if ($coupon->valid_from && $now < $coupon->valid_from) {
            return ['valid' => false, 'message' => 'Período de validade ainda não começou.'];
        }

        if ($coupon->valid_to && $now > $coupon->valid_to) {
            return ['valid' => false, 'message' => 'Período de validade terminou.'];
        }

        return ['valid' => true, 'message' => '', 'coupon' => $coupon];
