//| Função de inicialização do indicador                            |
//+------------------------------------------------------------------+
int OnInit()
  {
   // Associa o buffer ao indicador
   SetIndexBuffer(0, SMABuffer, INDICATOR_DATA);
   IndicatorSetString(INDICATOR_SHORTNAME, "SMA Alert (" + IntegerToString(SMA_Period) + ")");
   return(INIT_SUCCEEDED);
  }

//+------------------------------------------------------------------+
//| Função principal de cálculo                                     |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total,
                const int prev_calculated,
                const datetime &time[],
                const double &open[],
                const double &high[],
                const double &low[],
                const double &close[],
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
  {
   // Verifica se há dados suficientes
   if(rates_total <= SMA_Period)
      return(0);

   // Calcula a média móvel simples
   for(int i = MathMax(prev_calculated, rates_total - SMA_Period); i < rates_total; i++)
     {
      double sum = 0.0;
      for(int j = 0; j < SMA_Period; j++)
         sum += close[i - j];
      SMABuffer[i] = sum / SMA_Period;
     }

   // Verifica se deve disparar alerta
   CheckAlerts();

   return(rates_total);
  }

//+------------------------------------------------------------------+
//| Verifica condições para emitir alertas                         |
//+------------------------------------------------------------------+
void CheckAlerts()
  {
   // Preço atual e valor da SMA no último candle
   double currentPrice = close[rates_total - 1];
   double smaValue = SMABuffer[rates_total - 1];

   // Distância entre preço e média
   double distance = MathAbs(currentPrice - smaValue);

   // Dispara alerta se dentro da sensibilidade e não for o mesmo preço
   if(distance <= Sensibilidade * _Point && PreviousAlertPrice != currentPrice)
     {
      string msg = "O preço tocou ou chegou perto da SMA! Preço: " + DoubleToString(currentPrice, _Digits);
      Alert(msg);

      if(Notificacao_Ativa)
         SendNotification(msg);

      PreviousAlertPrice = currentPrice;
     }
  }
