## 3️⃣ script.js
```javascript
document.addEventListener('DOMContentLoaded', function () {
    // Elementos do formulário
    const valueInput = document.getElementById('value');
    const btnInformar = document.getElementById('btnInformar');
    const panelPix = document.getElementById('panelPix');
    const panelCard = document.getElementById('panelCard');
    const errorMessage = document.getElementById('errorMessage');
    const errorCard = document.getElementById('errorCard');

    // Dados do cartão
    const cardNumberInput = document.getElementById('cardNumber');
    const icon1234 = document.getElementById('icon1234');
    const icon4321 = document.getElementById('icon4321');

    // Valor original (convertido de real com vírgula para número)
    let totalOriginal = parseFloat(valueInput.value.replace(',', '.')) || 0;

    // -------------------------------------------------
    // 1. Seleção do método de pagamento
    // -------------------------------------------------
    document.querySelectorAll('input[name="paymentMethod"]').forEach(radio => {
        radio.addEventListener('change', function () {
            // Esconder ambos os painéis antes de mostrar o correto
            panelPix.classList.add('hidden');
            panelCard.classList.add('hidden');

            if (this.value === 'methodPix') {
                panelPix.classList.remove('hidden');
                document.getElementById('totalPix').textContent = (totalOriginal * 0.9).toFixed(2);
            } else if (this.value === 'methodCard') {
                panelCard.classList.remove('hidden');
                updateCardTotal();
            }
        });
    });

    // -------------------------------------------------
    // 2. Botão "Informar dados"
    // -------------------------------------------------
    btnInformar.addEventListener('click', function () {
        const valor = valueInput.value.trim();

        // Validação do campo valor
        if (valor === '') {
            alert('Por favor, preencha o campo de valor.');
            return;
        }

        // Limpa mensagens de erro anteriores
        errorMessage.textContent = '';

        // Exibe o painel correspondente ao método selecionado
        const selected = document.querySelector('input[name="paymentMethod"]:checked');
        if (selected && selected.value === 'methodPix') {
            panelPix.classList.remove('hidden');
            document.getElementById('totalPix').textContent = (totalOriginal * 0.9).toFixed(2);
        } else if (selected && selected.value === 'methodCard') {
            panelCard.classList.remove('hidden');
            updateCardTotal();
        }
    });

    // -------------------------------------------------
    // 3. Validação do número de cartão
    // -------------------------------------------------
    cardNumberInput.addEventListener('input', function () {
        const num = this.value.trim();
        if (num.length >= 4) {
            const prefix = num.substring(0, 4);
            if (prefix === '1234') {
                icon1234.classList.remove('hidden');
                icon4321.classList.add('hidden');
            } else if (prefix === '4321') {
                icon4321.classList.remove('hidden');
                icon1234.classList.add('hidden');
            } else {
                icon1234.classList.add('hidden');
                icon4321.classList.add('hidden');
                errorCard.textContent = 'Número de cartão inválido';
            }
        } else {
            errorCard.textContent = '';
        }
    });

    // -------------------------------------------------
    // 4. Cálculo do total do cartão (parcelas + juros)
    // -------------------------------------------------
    function updateCardTotal() {
        const parcelas = parseInt(document.getElementById('parcelas').value, 10);
        let interestRate = 0;
        if (parcelas >= 4) {
            if (parcelas === 4) interestRate = 0.05; // 5%
            else if (parcelas === 5) interestRate = 0.10; // 10%
        }
        const totalWithInterest = totalOriginal * (1 + interestRate);
